<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Golden Bird</title>
<style>
html,body{margin:0;width:240px;height:294px;overflow:hidden;background:#f8faff}
canvas{display:block;width:240px;height:294px}
</style>
</head>
<body>
<script type="module">
import * as THREE from 'three';

const scene = new THREE.Scene();
scene.background = new THREE.Color(0xf8faff);
scene.fog = new THREE.Fog(0xf8faff, 12, 27);

const renderer = new THREE.WebGLRenderer({ preserveDrawingBuffer: true });
renderer.setPixelRatio(1);
renderer.setSize(240, 294);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 0.96;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

const viewHeight = 4.704;
const ref = new THREE.OrthographicCamera(
  -viewHeight * 240 / 294 / 2,
   viewHeight * 240 / 294 / 2,
   viewHeight / 2,
  -viewHeight / 2, 0.1, 100
);
ref.name = 'reference-camera';
ref.position.set(0.30, 3.40, 10);
ref.lookAt(0.30, 2.40, 0);

scene.add(new THREE.HemisphereLight(0xfffff2, 0xaaa5a0, 1.45));

const key = new THREE.DirectionalLight(0xfff6dd, 2.7);
key.position.set(-3.5, 7, 5);
key.castShadow = true;
key.shadow.mapSize.set(1024, 1024);
key.shadow.camera.left = -3;
key.shadow.camera.right = 3;
key.shadow.camera.top = 6;
key.shadow.camera.bottom = -1;
key.shadow.camera.near = 0.5;
key.shadow.camera.far = 20;
key.shadow.normalBias = 0.025;
key.shadow.bias = -0.0002;
key.shadow.radius = 4;
key.target.position.set(0, 2, 0);
scene.add(key, key.target);

const backLight = new THREE.DirectionalLight(0xf3f5ff, 1.15);
backLight.position.set(3, 5, -5);
scene.add(backLight);
const fill = new THREE.DirectionalLight(0xffffff, 0.45);
fill.position.set(4, 3, 5);
scene.add(fill);

const floor = new THREE.Mesh(
  new THREE.PlaneGeometry(200, 200),
  new THREE.MeshStandardMaterial({color:0xd5d4c9,roughness:1})
);
floor.name = 'matte-ground';
floor.rotation.x = -Math.PI / 2;
floor.position.y = -0.23;
floor.receiveShadow = true;
scene.add(floor);

let seed = 19387;
function rand() {
  seed = (Math.imul(seed,1664525) + 1013904223) >>> 0;
  return seed / 4294967296;
}
const grainData = new Uint8Array(64*64*4);
for(let i=0;i<64*64;i++){
  const v = 110 + Math.floor(rand()*115);
  grainData[i*4]=v;
  grainData[i*4+1]=v;
  grainData[i*4+2]=v;
  grainData[i*4+3]=255;
}
const grain = new THREE.DataTexture(grainData,64,64,THREE.RGBAFormat);
grain.wrapS = grain.wrapT = THREE.RepeatWrapping;
grain.repeat.set(4,4);
grain.magFilter = THREE.LinearFilter;
grain.minFilter = THREE.LinearFilter;
grain.needsUpdate = true;

function material(color, extra={}) {
  return new THREE.MeshStandardMaterial({
    color, roughness:0.98, metalness:0,
    bumpMap:grain, bumpScale:0.004,
    dithering:true, ...extra
  });
}
const plumage = material(0xffffff,{vertexColors:true});
const headMat = material(0xf2c222);
const lidMat = material(0xecc027);
const beakMat = material(0xdcc12a);
const lowerBeakMat = material(0xc4a62b);
const mouthMat = material(0x76672a,{bumpMap:null});
const socketMat = material(0xb1a64b,{bumpMap:null});
const pupilMat = material(0x42442b,{bumpMap:null,roughness:0.72});
const handMat = material(0x626047,{bumpScale:0.003});
const fingerMat = material(0x4e503b,{bumpScale:0.002});
const footMat = material(0xe3a619);

function group(name,parent,x=0,y=0,z=0){
  const g = new THREE.Group();
  g.name=name;
  g.position.set(x,y,z);
  if(parent)parent.add(g);
  return g;
}
function ellipsoid(name,parent,mat,x,y,z,sx,sy,sz){
  const m = new THREE.Mesh(new THREE.SphereGeometry(1,32,24),mat);
  m.name=name;
  m.position.set(x,y,z);
  m.scale.set(sx,sy,sz);
  m.castShadow=true;
  m.receiveShadow=true;
  parent.add(m);
  return m;
}

// Profiles contain [height, horizontal center, width, depth, depth center].
function sample(rows,y,k){
  let i=0;
  while(i<rows.length-2 && y>rows[i+1][0])i++;
  const a=rows[i], b=rows[i+1];
  const p=rows[Math.max(0,i-1)], n=rows[Math.min(rows.length-1,i+2)];
  const d=b[0]-a[0], t=Math.max(0,Math.min(1,(y-a[0])/d));
  const m0=(b[k]-p[k])/(b[0]-p[0]);
  const m1=(n[k]-a[k])/(n[0]-a[0]);
  return (2*t*t*t-3*t*t+1)*a[k]
    +(t*t*t-2*t*t+t)*d*m0
    +(-2*t*t*t+3*t*t)*b[k]
    +(t*t*t-t*t)*d*m1;
}
function profileMesh(name,parent,rows,mat,colorFn){
  const heightSteps=88, sides=64;
  const pos=[],uv=[],colors=[],indices=[];
  const y0=rows[0][0], y1=rows[rows.length-1][0];
  for(let i=0;i<=heightSteps;i++){
    const y=THREE.MathUtils.lerp(y0,y1,i/heightSteps);
    const cx=sample(rows,y,1), rx=Math.max(0,sample(rows,y,2));
    const rz=Math.max(0,sample(rows,y,3)), cz=sample(rows,y,4);
    for(let j=0;j<=sides;j++){
      const angle=j/sides*Math.PI*2;
      const x=cx+rx*Math.cos(angle), z=cz+rz*Math.sin(angle);
      pos.push(x,y,z);
      uv.push(j/sides,i/heightSteps);
      if(colorFn){
        const c=colorFn(x,y,z,angle);
        colors.push(c.r,c.g,c.b);
      }
      if(i<heightSteps && j<sides){
        const a=i*(sides+1)+j,b=a+sides+1;
        indices.push(a,b,b+1,a,b+1,a+1);
      }
    }
  }
  const geo=new THREE.BufferGeometry();
  geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));
  geo.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));
  if(colorFn)geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));
  geo.setIndex(indices);
  geo.computeVertexNormals();
  const mesh=new THREE.Mesh(geo,mat);
  mesh.name=name;
  mesh.castShadow=true;
  mesh.receiveShadow=true;
  parent.add(mesh);
  return mesh;
}
function taperedCurve(name,parent,points,r0,r1,mat){
  const curve=new THREE.CatmullRomCurve3(points.map(p=>new THREE.Vector3(...p)));
  const count=20,sides=9;
  const frames=curve.computeFrenetFrames(count,false);
  const positions=[],uvs=[],indices=[];
  for(let i=0;i<=count;i++){
    const t=i/count,p=curve.getPointAt(t);
    const r=THREE.MathUtils.lerp(r0,r1,t);
    for(let j=0;j<=sides;j++){
      const a=j/sides*Math.PI*2;
      const v=p.clone()
        .addScaledVector(frames.normals[i],Math.cos(a)*r)
        .addScaledVector(frames.binormals[i],Math.sin(a)*r);
      positions.push(v.x,v.y,v.z);
      uvs.push(j/sides,t);
      if(i<count && j<sides){
        const k=i*(sides+1)+j,l=k+sides+1;
        indices.push(k,k+1,l+1,k,l+1,l);
      }
    }
  }
  const start=positions.length/3;
  const p0=curve.getPointAt(0),p1=curve.getPointAt(1);
  positions.push(p0.x,p0.y,p0.z,p1.x,p1.y,p1.z);
  uvs.push(.5,0,.5,1);
  for(let j=0;j<sides;j++){
    indices.push(start,j+1,j);
    const k=count*(sides+1)+j;
    indices.push(start+1,k,k+1);
  }
  const geometry=new THREE.BufferGeometry();
  geometry.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));
  geometry.setAttribute('uv',new THREE.Float32BufferAttribute(uvs,2));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  const mesh=new THREE.Mesh(geometry,mat);
  mesh.name=name;
  mesh.castShadow=true;
  parent.add(mesh);
  return mesh;
}

const bird=group('golden-bird',scene);
const body=group('body-and-neck',bird);

const gold=new THREE.Color(0xf2bb1e);
const orange=new THREE.Color(0xeda91b);
const cream=new THREE.Color(0xffdd83);
profileMesh('continuous-pear-shaped-body',body,[
  [1.035,-.025,0,0,.01],
  [1.14,-.025,.46,.36,.015],
  [1.34,-.025,.67,.49,.035],
  [1.60,-.025,.83,.59,.065],
  [1.94,-.025,.93,.65,.075],
  [2.23,-.035,.895,.635,.065],
  [2.53,-.04,.80,.57,.035],
  [2.82,-.025,.69,.49,.005],
  [3.08,0,.63,.405,-.005],
  [3.34,.025,.54,.34,-.018],
  [3.56,.035,.43,.30,-.015],
  [3.78,.04,.335,.275,-.01],
  [3.99,.04,.285,.25,-.005],
  [4.12,.04,0,0,0]
],plumage,(x,y,z,a)=>{
  const front=Math.pow(Math.max(0,Math.sin(a)),1.1);
  const belly=Math.exp(-Math.pow((x+.07)/.69,2)-Math.pow((y-2.46)/.93,2))*front;
  const base=orange.clone().lerp(gold,THREE.MathUtils.smoothstep(y,1.3,3.4));
  return base.lerp(cream,belly*.91);
});

function makeLeg(side){
  const left=side<0;
  const leg=group(left?'left-leg':'right-leg',bird);
  const topX=left?-.36:.31;
  const ankleX=left?-.22:.32;
  const legOrange=new THREE.Color(left?0xeaa51a:0xe8ac1e);
  const legGold=new THREE.Color(0xf4bb29);
  profileMesh('tapered-leg',leg,[
    [-.36,ankleX,0,0,.02],
    [-.20,ankleX,.185,.205,.02],
    [.10,ankleX,.205,.235,.02],
    [.46,left?-.27:.31,.235,.27,.015],
    [.86,left?-.33:.31,.275,.305,0],
    [1.18,topX,left?.315:.285,.345,-.025],
    [1.46,topX,.30,.32,-.035],
    [1.65,topX,0,0,-.04]
  ],plumage,(x,y,z,a)=>{
    const f=Math.max(0,Math.sin(a));
    return legOrange.clone().lerp(legGold,.28*f);
  });
  const foot=group(left?'left-foot':'right-foot',leg,ankleX,-.30,.095);
  ellipsoid('rounded-foot',foot,footMat,0,-.035,.085,.235,.105,.32);
  for(let i=0;i<3;i++){
    const toe=group('toe-'+(i+1),foot);
    ellipsoid('toe',toe,footMat,(i-1)*.115,-.045,.30,.065,.065,.19);
  }
}
makeLeg(-1);
makeLeg(1);

function makeHand(parent,side){
  const hand=group(side<0?'left-hand':'right-hand',parent);
  const palm=group('palm',hand);
  const palmMesh=ellipsoid('olive-palm',palm,handMat,side*.025,-.105,.025,.105,.14,.068);
  palmMesh.rotation.z=side*.10;
  const lengths=[.20,.265,.28,.22];
  for(let i=0;i<4;i++){
    const f=group('finger-'+(i+1),hand);
    const x=(i-1.5)*.052+side*.025;
    const dx=(i-1.5)*.025+side*.014;
    const len=lengths[i];
    const end=[x+dx,-.17-len,.05];
    taperedCurve('curved-finger',f,[
      [x,-.16,.035],
      [x+dx*.4,-.22,.057],
      [x+dx*.85,-.17-len*.72,.065],
      end
    ],.029,.012,fingerMat);
    ellipsoid('rounded-fingertip',f,fingerMat,...end,.013,.017,.014);
  }
  const thumb=group('thumb',hand);
  taperedCurve('bent-thumb',thumb,[
    [-side*.062,-.055,.045],
    [-side*.12,-.10,.073],
    [-side*.145,-.18,.081],
    [-side*.13,-.25,.07]
  ],.036,.017,handMat);
  ellipsoid('thumb-tip',thumb,handMat,-side*.13,-.25,.07,.017,.022,.018);
  return hand;
}
function makeArm(side){
  const left=side<0;
  const sy=left?3.25:3.27;
  const sx=left?-.65:.62;
  const length=left?1.43:1.55;
  const dx=left?-.40:.39;
  const arm=group(left?'left-arm':'right-arm',bird,sx,sy,left?-.045:-.12);
  const wing=group('wing',arm);
  const wingGold=new THREE.Color(0xeeb919);
  const wingLight=new THREE.Color(0xf7c523);
  const wristColor=new THREE.Color(0x9f9135);
  profileMesh('long-tapering-wing',wing,[
    [-length-.045,dx,0,0,.15],
    [-length,dx,.058,.067,.15],
    [-length+.19,dx*.94,.072,.083,.12],
    [-length+.46,dx*.75,.092,.105,.075],
    [-.65,dx*.57,.117,.135,.025],
    [-.27,dx*.26,.15,.16,0],
    [.04,0,.15,.155,-.015],
    [.17,-side*.015,0,0,-.025]
  ],plumage,(x,y,z,a)=>{
    const front=Math.max(0,Math.sin(a));
    const c=wingGold.clone().lerp(wingLight,front*.25);
    return c.lerp(wristColor,1-THREE.MathUtils.smoothstep(y,-length,-length+.22));
  });
  const hand=makeHand(arm,side);
  hand.position.set(dx,-length,.15);
  hand.rotation.z=left?-.11:.12;
}
makeArm(-1);
makeArm(1);

const head=group('head',bird,.04,4.08,-.015);
head.rotation.y=.13;
ellipsoid('rounded-feathered-skull',head,headMat,0,0,0,.35,.405,.313);

const crown=group('crown-feathers',head);
for(let i=0;i<13;i++){
  const x=(rand()-.5)*.35;
  const z=(rand()-.5)*.22;
  const y=.405*Math.sqrt(Math.max(0,1-x*x/(.35*.35)-z*z/(.313*.313)));
  const feather=ellipsoid('small-crown-feather-'+i,crown,headMat,x,y-.012,z,.022,.035,.023);
  feather.rotation.z=(rand()-.5)*.35;
}

const eyes=group('eyes',head);
function makeEye(side){
  const eye=group(side<0?'left-eye':'right-eye',eyes,side*.165,.105,.267);
  eye.rotation.y=side*.22;
  ellipsoid('muted-golden-eye',eye,socketMat,0,0,0,.064,.041,.026);
  ellipsoid('small-dark-pupil',eye,pupilMat,side*.004,-.001,.024,.024,.023,.012);
  const upper=group('upper-eyelid',eye);
  const lid=ellipsoid('heavy-yellow-lid',upper,lidMat,0,.028,.014,.077,.026,.032);
  lid.rotation.z=side*.07;
  ellipsoid('lower-eyelid',eye,headMat,0,-.032,.009,.069,.013,.026);
  const brow=ellipsoid('soft-brow',eye,headMat,-side*.003,.064,-.016,.085,.033,.035);
  brow.rotation.z=-side*.10;
}
makeEye(-1);
makeEye(1);

const mouth=group('beak-and-mouth',head,.012,-.078,.286);
ellipsoid('lower-bill',mouth,lowerBeakMat,0,-.018,.094,.169,.037,.133);
ellipsoid('short-upper-bill',mouth,beakMat,0,.025,.092,.194,.063,.162);
taperedCurve('quiet-mouth-line',mouth,[
  [-.164,-.013,.151],
  [-.105,-.022,.219],
  [.005,-.026,.246],
  [.105,-.021,.222],
  [.169,-.010,.154]
],.007,.005,mouthMat);
const nostrils=group('nostrils',mouth);
ellipsoid('left-nostril',nostrils,lowerBeakMat,-.080,.054,.205,.012,.006,.006);
ellipsoid('right-nostril',nostrils,lowerBeakMat,.080,.054,.205,.012,.006,.006);

function render(t){
  renderer.render(scene,ref);
}
window.nwb={
  scene,
  renderer,
  cameras:{ref},
  characters:[bird],
  render,
  ready:true
};
render(0);
</script>
</body>
</html>
